import * as THREE from './assets/three.module.js';
import {terrainInfo,weapons} from './engine.js';
export class ArenaView{
constructor(element,battle){this.el=element;this.battle=battle;this.disposed=false;this.zoom=1;this.orbit=0;this.meshes=new Map();this.scene=new THREE.Scene();this.scene.background=new THREE.Color(0x18292f);this.scene.fog=new THREE.Fog(0x18292f,95,170);this.renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});this.renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));this.renderer.shadowMap.enabled=true;this.renderer.shadowMap.type=THREE.PCFSoftShadowMap;this.renderer.outputColorSpace=THREE.SRGBColorSpace;this.el.prepend(this.renderer.domElement);this.camera=new THREE.PerspectiveCamera(42,1,.1,250);this.scene.add(new THREE.HemisphereLight(0xd9f2ff,0x273427,2.3));const light=new THREE.DirectionalLight(0xfff3d7,3);light.position.set(-22,45,15);light.castShadow=true;light.shadow.mapSize.set(1024,1024);Object.assign(light.shadow.camera,{left:-50,right:50,top:40,bottom:-40});light.shadow.bias=-.001;this.scene.add(light);
this.ground(battle.terrain);for(const unit of battle.units)this.makePlayer(unit);this.lines=new THREE.Group();this.scene.add(this.lines);this.clock=new THREE.Clock();this.observer=new ResizeObserver(()=>this.resize());this.observer.observe(element);this.resize();this.frame();}
material(color){return new THREE.MeshStandardMaterial({color,roughness:.8,metalness:.05});}
mesh(geo,mat,parent=this.scene){const m=new THREE.Mesh(geo,mat);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
ground(terrain){const mat=this.material(terrainInfo[terrain].color);const base=this.mesh(new THREE.BoxGeometry(76,1.2,56),this.material(0x263a3c));base.position.y=-.8;const geo=new THREE.PlaneGeometry(72,52,36,26);geo.rotateX(-Math.PI/2);if(terrain==='mountain'){const pos=geo.attributes.position;for(let i=0;i<pos.count;i++){const x=pos.getX(i),z=pos.getZ(i);pos.setY(i,this.height(x,z));}geo.computeVertexNormals();}this.mesh(geo,mat);
const grid=new THREE.GridHelper(72,18,0x7b9b85,0x537065);grid.material.transparent=true;grid.material.opacity=terrain==='snow'?.13:.18;grid.position.y=.04;this.scene.add(grid);
const rails=this.material(0x45656d),lights=new THREE.MeshBasicMaterial({color:0x6bd3cb});for(const z of [-27,27]){const rail=this.mesh(new THREE.BoxGeometry(76,.6,.6),rails);rail.position.set(0,.4,z);const line=this.mesh(new THREE.BoxGeometry(72,.07,.1),lights);line.position.set(0,.8,z);}for(const x of [-37,37]){const rail=this.mesh(new THREE.BoxGeometry(.6,.6,54),rails);rail.position.set(x,.4,0);}
for(const x of [-32,32]){const spawn=this.mesh(new THREE.PlaneGeometry(5,42),new THREE.MeshBasicMaterial({color:x<0?0x3bc4bd:0xee977f,transparent:true,opacity:.15,side:THREE.DoubleSide}));spawn.rotation.x=-Math.PI/2;spawn.position.set(x,.06,0);}
this.flagMeshes=new Map();
for(const flag of this.battle.flags){
 const color=flag.team===0?0x3bc4bd:0xee977f,group=new THREE.Group();
 const ring=this.mesh(new THREE.RingGeometry(2,2.2,32),new THREE.MeshBasicMaterial({color,side:THREE.DoubleSide,transparent:true,opacity:.75}),group);ring.rotation.x=-Math.PI/2;ring.position.y=.08;
 const disc=this.mesh(new THREE.CircleGeometry(2,32),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.12,side:THREE.DoubleSide}),group);disc.rotation.x=-Math.PI/2;disc.position.y=.06;
 group.position.set(flag.home.x,this.height(flag.home.x,flag.home.z),flag.home.z);group.visible=this.battle.modeIndex===1;this.scene.add(group);
 const standard=new THREE.Group();const pole=this.mesh(new THREE.CylinderGeometry(.065,.065,3.8,6),this.material(0xd4dedd),standard);pole.position.y=1.9;
 const banner=this.mesh(new THREE.PlaneGeometry(2.4,1.35),new THREE.MeshStandardMaterial({color,side:THREE.DoubleSide,roughness:.8}),standard);banner.position.set(1.2,3,0);standard.visible=this.battle.modeIndex===1;this.scene.add(standard);
 this.flagMeshes.set(flag.id,{group,standard,banner,ring});
}
this.baseMarkers=[];
for(let team=0;team<2;team++){
 const base=this.battle.bases[team],color=team===0?0x3bc4bd:0xee977f;
 const marker=this.mesh(new THREE.RingGeometry(3.8,4.1,48),new THREE.MeshBasicMaterial({color,side:THREE.DoubleSide,transparent:true,opacity:.75}));marker.rotation.x=-Math.PI/2;marker.position.set(base.x,this.height(base.x,base.z)+.1,base.z);marker.visible=this.battle.modeIndex===1;this.baseMarkers.push(marker);
}
// The terrain scenery stays outside the main movement lanes in this prototype.
for(let i=0;i<18;i++){const x=(i%2?1:-1)*(8+(i%6)*4),z=(i<9?-1:1)*(22+((i*7)%5));if(terrain==='forest'){const trunk=this.mesh(new THREE.CylinderGeometry(.25,.4,3,6),this.material(0x604b38));trunk.position.set(x,1.4,z);for(let j=0;j<2;j++){const tree=this.mesh(new THREE.ConeGeometry(2.1-j*.5,4,7),this.material(j?0x41644b:0x274936));tree.position.set(x,4+j*1.5,z);}}else if(terrain==='city'){const b=this.mesh(new THREE.BoxGeometry(3,2+i%3,2),this.material(i%2?0x718383:0x384d52));b.position.set(x,1+i%3*.5,z);const stripe=this.mesh(new THREE.BoxGeometry(3.05,.12,2.05),lights);stripe.position.set(x,1.4+i%3*.5,z);}else{const rock=this.mesh(new THREE.DodecahedronGeometry(1.6+(i%3)*.4,0),this.material(terrain==='snow'?0xd3dfdf:0x78877b));rock.position.set(x,.8,z);rock.scale.y=1.5;}}
for(const x of [-45,45]){const stand=this.mesh(new THREE.BoxGeometry(8,5,58),this.material(0x253a42));stand.position.set(x,1.2,0);for(let k=0;k<5;k++){const row=this.mesh(new THREE.BoxGeometry(8,.25,58),this.material(0x46616a));row.position.set(x,-.6+k,0);}}
}
height(x,z){return this.battle.terrain==='mountain'?Math.sin(x*.085)*Math.cos(z*.07)*1.7:0;}
makePlayer(u){const root=new THREE.Group(),rig=new THREE.Group();root.add(rig);const color=u.team===0?0x42c7be:0xf19a81;const shirt=this.material(color),black=this.material(0x243139),skin=this.material(u.p.portrait%3===0?0xb17b5d:0xe2b296),hair=this.material([0x242126,0x49342a,0xa5a3a0,0x82412e][(u.p.portrait||0)%4]);const body=this.mesh(new THREE.CapsuleGeometry(.42,.65,4,8),shirt,rig);body.position.y=1.35;const head=this.mesh(new THREE.SphereGeometry(.31,8,8),skin,rig);head.position.y=2.12;const hairCap=this.mesh(new THREE.SphereGeometry(.325,8,6,0,Math.PI*2,0,1.65),hair,rig);hairCap.position.y=2.18;const pony=this.mesh(new THREE.ConeGeometry(.2,.65,6),hair,rig);pony.position.set(0,1.9,-.3);pony.rotation.x=.5;
const limbs=[];for(const side of [-1,1]){const leg=this.mesh(new THREE.CapsuleGeometry(.13,.65,3,5),black,rig);leg.position.set(side*.22,.48,0);limbs.push(leg);const armPivot=new THREE.Group();armPivot.position.set(side*.5,1.65,0);rig.add(armPivot);const arm=this.mesh(new THREE.CapsuleGeometry(.12,.55,3,5),shirt,armPivot);arm.position.y=-.32;limbs.push(armPivot);}
const weapon=new THREE.Group();weapon.position.set(.65,1.3,.35);rig.add(weapon);const steel=this.material(0xd8e2e4),wood=this.material(0x684e35);let len=1.1;if([3,9,11].includes(u.p.weapon))len=2.6;if([1,8].includes(u.p.weapon))len=1.7;
if([4,10].includes(u.p.weapon)){const arc=new THREE.EllipseCurve(0,0,.45,.9,-Math.PI/2,Math.PI/2,false,0);const shape=new THREE.TubeGeometry(new THREE.CatmullRomCurve3(arc.getPoints(16).map(p=>new THREE.Vector3(p.x,p.y,0))),16,.04,4,false);this.mesh(shape,wood,weapon);const string=this.mesh(new THREE.CylinderGeometry(.015,.015,1.8,4),steel,weapon);string.position.x=0;}
else if(u.p.weapon===7||u.p.weapon===11){const curve=new THREE.CatmullRomCurve3([new THREE.Vector3(0,0,0),new THREE.Vector3(.7,.1,.4),new THREE.Vector3(1.5,-.1,.9),new THREE.Vector3(2,-.2,1.4)]);this.mesh(new THREE.TubeGeometry(curve,12,.035,4,false),wood,weapon);}
else{const shaft=this.mesh(new THREE.BoxGeometry(.07,len,.07),[3,9].includes(u.p.weapon)?wood:steel,weapon);shaft.rotation.x=Math.PI/2;shaft.position.z=len/2;if(u.p.weapon===5){const hammer=this.mesh(new THREE.BoxGeometry(.6,.35,.3),steel,weapon);hammer.position.z=len;}if(u.p.weapon===0){const shield=this.mesh(new THREE.CylinderGeometry(.48,.48,.12,8),this.material(u.team===0?0x255952:0x804c3c),rig);shield.rotation.x=Math.PI/2;shield.position.set(-.6,1.35,.2);}}
const ring=this.mesh(new THREE.RingGeometry(.65,.82,24),new THREE.MeshBasicMaterial({color,side:THREE.DoubleSide}),root);ring.rotation.x=-Math.PI/2;ring.position.y=.06;
const barBg=this.mesh(new THREE.PlaneGeometry(1.6,.15),new THREE.MeshBasicMaterial({color:0x142329,side:THREE.DoubleSide}),root);barBg.position.set(0,2.7,0);const hp=this.mesh(new THREE.PlaneGeometry(1.55,.1),new THREE.MeshBasicMaterial({color:0xc1ee69,side:THREE.DoubleSide}),root);hp.position.set(0,2.7,.015);const crown=this.mesh(new THREE.OctahedronGeometry(.24),new THREE.MeshBasicMaterial({color:0xf5dc80}),root);crown.position.y=3.2;crown.visible=u.king;root.scale.setScalar(1.05);this.scene.add(root);this.meshes.set(u.id,{root,rig,limbs,weapon,hp,barBg,crown,lastX:u.x,lastZ:u.z});}
setBattle(battle){for(const obj of this.meshes.values()){this.scene.remove(obj.root);obj.root.traverse(o=>{if(o.geometry)o.geometry.dispose();if(o.material)o.material.dispose();});}this.meshes.clear();this.battle=battle;for(const u of battle.units)this.makePlayer(u);for(const m of this.flagMeshes.values()){m.group.visible=battle.modeIndex===1;m.standard.visible=battle.modeIndex===1;}for(const m of this.baseMarkers)m.visible=battle.modeIndex===1;}
resize(){const {width,height}=this.el.getBoundingClientRect();this.renderer.setSize(Math.max(1,width),Math.max(1,height));this.camera.aspect=width/Math.max(1,height);this.camera.updateProjectionMatrix();}
frame(){if(this.disposed)return;this.frameId=requestAnimationFrame(()=>this.frame());const t=this.clock.getElapsedTime();this.camera.position.set(Math.sin(this.orbit)*65*this.zoom,58*this.zoom,Math.cos(this.orbit)*64*this.zoom);this.camera.lookAt(0,0,0);for(const u of this.battle.units){const m=this.meshes.get(u.id);if(!m)continue;m.root.position.set(u.x,this.height(u.x,u.z)+.1,u.z);m.rig.rotation.y=u.angle;m.root.visible=u.alive;const moving=Math.hypot(u.x-m.lastX,u.z-m.lastZ)>.01;m.lastX=u.x;m.lastZ=u.z;const walk=moving?Math.sin(t*9+u.id)*.4:0;m.limbs[0].rotation.x=walk;m.limbs[2].rotation.x=-walk;m.limbs[1].rotation.x=u.animation>0?-1.4:-walk*.5;m.limbs[3].rotation.x=walk*.5;m.weapon.visible=u.armed;m.weapon.rotation.y=u.animation>0?Math.sin(u.animation*8)*1.2:0;m.hp.scale.x=Math.max(.01,u.hp/100);m.hp.quaternion.copy(this.camera.quaternion);m.barBg.quaternion.copy(this.camera.quaternion);m.crown.rotation.y=t;}
for(const flag of this.battle.flags){
 const m=this.flagMeshes.get(flag.id);if(!m)continue;
 m.group.visible=this.battle.modeIndex===1;
 m.standard.visible=this.battle.modeIndex===1&&flag.capturedBy===null;
 m.group.position.y=this.height(flag.home.x,flag.home.z)+.03;
 m.ring.material.opacity=flag.capturedBy!==null?.15:flag.carrierId!==null?.3:.75;
 m.standard.position.set(flag.x,this.height(flag.x,flag.z)+(flag.carrierId!==null?1.2:.05),flag.z);
 m.standard.rotation.z=flag.dropped?Math.PI*.43:0;m.banner.rotation.y=Math.sin(t*3+flag.id)*.12;
}
for(const child of [...this.lines.children]){this.lines.remove(child);child.geometry.dispose();child.material.dispose();}for(const e of this.battle.events){const points=[new THREE.Vector3(e.from.x,1.5+this.height(e.from.x,e.from.z),e.from.z),new THREE.Vector3(e.to.x,1.5+this.height(e.to.x,e.to.z),e.to.z)];if(e.ranged){const mid=points[0].clone().lerp(points[1],.5);mid.y+=3;points.splice(1,0,mid);}const line=new THREE.Line(new THREE.BufferGeometry().setFromPoints(points),new THREE.LineBasicMaterial({color:e.hit?0xe8ecbd:0x9eaab0,transparent:true,opacity:.7}));this.lines.add(line);}this.renderer.render(this.scene,this.camera);}
dispose(){this.disposed=true;cancelAnimationFrame(this.frameId);this.observer.disconnect();this.scene.traverse(o=>{if(o.geometry)o.geometry.dispose();if(o.material)o.material.dispose();});this.renderer.dispose();this.renderer.domElement.remove();}
}
